from collections import deque

def get_components(grid):
    """Get list of connected components with their structure"""
    visited = set()
    components = []

    for r in range(len(grid)):
        for c in range(len(grid[0])):
            if grid[r][c] != 0 and (r,c) not in visited:
                color = grid[r][c]
                # BFS to find all cells in this component
                component_cells = []
                queue = deque([(r, c)])
                visited.add((r,c))

                while queue:
                    cr, cc = queue.popleft()
                    component_cells.append((cr, cc))
                    for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
                        nr, nc = cr + dr, cc + dc
                        if 0 <= nr < len(grid) and 0 <= nc < len(grid[0]):
                            if grid[nr][nc] == color and (nr, nc) not in visited:
                                visited.add((nr, nc))
                                queue.append((nr, nc))

                components.append({'color': color, 'cells': sorted(component_cells)})

    return components

def apply_gravity_to_component(grid, comp_cells, height=10):
    """Move a component down until it can't move further"""
    new_positions = list(comp_cells)
    moved = True

    while moved:
        moved = False
        # Sort by column then row to process bottom-up within columns
        new_positions.sort(key=lambda x: (-x[0], x[1]))

        for i, (r, c) in enumerate(new_positions):
            # Try moving down
            if r > 0:
                below_empty = all(grid[r-1-d][c] == 0 for d in range(i+1))
                if below_empty:
                    new_positions[i] = (r-1, c)
                    moved = True

    return new_positions

def simulate_component_fall(d_in):
    """Simulate all components falling down together"""
    components = get_components(d_in)

    # Create empty grid
    result = [[0]*len(d_in[0]) for _ in range(len(d_in))]

    for comp in components:
        shifted = apply_gravity_to_component(d_in, comp['cells'])
        for r, c in shifted:
            result[r][c] = comp['color']

    return result

