def get_all_components(grid):
    """Get all connected components with their relative shapes."""
    visited = set()
    components = []

    for r in range(10):
        for c in range(10):
            if grid[r,c] != 0 and (r,c) not in visited:
                # Start new component
                component_pixels = set()
                queue = [(r,c)]

                while queue:
                    cr, cc = queue.pop(0)
                    if (cr,cc) not in visited:
                        visited.add((cr,cc))
                        component_pixels.add((cr,cc))

                        color = int(grid[cr,cc])
                        for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
                            nr, nc = cr+dr, cc+dc
                            if 0 <= nr < 10 and 0 <= nc < 10:
                                neighbor_val = int(grid[nr,nc])
                                if neighbor_val == color and \
                                   (nr,nc) not in visited:
                                    queue.append((nr,nc))

                rs = [p[0] for p in component_pixels]
                cs = [p[1] for p in component_pixels]
                rmin, rmax = min(rs), max(rs)
                cmin, cmax = min(cs), max(cs)

                rel_coords = sorted([(p[0]-rmin, p[1]-cmin) for p in component_pixels])

                components.append({
                    'pixels': list(component_pixels),
                    'color': int(grid[component_pixels[0][0], component_pixels[0][1]]),
                    'bbox': (rmin, rmax, cmin, cmax),
                    'relative_shape': rel_coords,
                })

    return components

